CREATE TABLE IF NOT EXISTS collector_meta (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS collection_records (id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, group_id TEXT NOT NULL REFERENCES dedup_groups(id), status TEXT NOT NULL CHECK(status IN ('discovered','source_check_needed','dedup_excluded','verified_waiting','ready_to_publish')), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS dedup_groups (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS dedup_members (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES dedup_groups(id), record_id TEXT NOT NULL REFERENCES collection_records(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS evidence_assertions (id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES collection_records(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS group_evidence_links (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES dedup_groups(id), assertion_id TEXT NOT NULL REFERENCES evidence_assertions(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS evidence_conflicts (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES dedup_groups(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS review_events (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS collection_jobs (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS intake_reservations (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS intake_attempts (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS intake_receipts (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS daily_budgets (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS domain_state (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS seller_candidates (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS seller_candidate_sources (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS legacy_imports (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sync_outbox (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
PRAGMA user_version=1;
